const staticData = $getWorkflowStaticData('global');
const trade = $('Get Latest Congress Trade').first().json;
const recentResponse = $input.first().json;

const tradeId = String(trade.id ?? '');
const ticker = String(trade.ticker ?? '').trim().toUpperCase();
const lastTradeId = staticData.lastTradeId == null
  ? null
  : String(staticData.lastTradeId);

const recentPosts = Array.isArray(recentResponse.data)
  ? recentResponse.data.slice(0, 10)
  : [];

// Match the exact cashtag or hashtag, so ticker T does not match TSLA.
const escapedTicker = ticker.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const tickerPattern = ticker
  ? new RegExp(`(?:\\$|#)${escapedTicker}(?![A-Z0-9.])`, 'i')
  : null;

const matchingPost = tickerPattern
  ? recentPosts.find(post => tickerPattern.test(String(post.caption ?? '')))
  : null;

const isNewTrade = !lastTradeId || tradeId !== lastTradeId;
const tickerInLast10Posts = Boolean(matchingPost);
const shouldPublish = isNewTrade && !tickerInLast10Posts;

// Mark every new transaction as seen, including one skipped because its
// ticker appeared in the last 10 Instagram feed posts.
if (isNewTrade) {
  staticData.lastTradeId = tradeId;
}

return [{
  json: {
    ...trade,
    ticker,
    isNew: shouldPublish,
    skipReason: !isNewTrade
      ? 'duplicate_trade_id'
      : tickerInLast10Posts
        ? 'ticker_in_last_10_posts'
        : null,
    matchingInstagramPostId: matchingPost?.id ?? null,
    checkedInstagramPosts: recentPosts.length,
  },
}];

// The transaction was marked as seen before the branch.
// Keep this pass-through node so existing workflow connections remain stable.
return [{ json: $json }];

// Merge Claude tagline with original trade data
const claudeResp = $input.first().json;
const trade      = $('Check Trade and Recent Tickers').first().json;
const rawTagline = claudeResp?.content?.[0]?.text?.trim() || 'Trade like an insider.';
// Strip surrounding quotes if Claude added them
const tagline = rawTagline.replace(/^["']|["']$/g, '').trim();
return [{ json: { ...trade, tagline } }];

// Turn the DB row into ONE signed number the card can render.
//
// `transactions.performance` is NOT the stock's move when the filing is a sale.
// server/updatePerformance.ts computes:
//     buy  → (current - tx) / tx * 100
//     sell → (tx - current) / tx * 100     ← inverted: positive means the stock FELL
// It answers "did the filer do well?", which is the right column for the site's
// tables but the wrong number to print on a card. The card shows what the STOCK
// did since the disclosed transaction, so sales are sign-flipped. Without this a
// sale that saved the filer 18% renders as "+18%" and reads as a gain.
//
// /api/trades/congress/latest carries no performance at all, which is why the row
// has to be re-fetched from /api/quiver/transactions/stock/:ticker and matched by id.

const trade = $('Merge Tagline').first().json;

let rows = [];
try {
  rows = $input.all().map(i => i.json).filter(r => r && r.id);
} catch (e) {
  rows = [];
}

const row = rows.find(r => String(r.id) === String(trade.id)) || null;

const num = v => {
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const rawPerf = row ? num(row.performance) : null;
const txPrice = row ? num(row.transactionPrice ?? row.transaction_price) : null;
const nowPrice = row ? num(row.currentPrice ?? row.current_price) : null;

// "vente" is what the DB stores for a sale; the API passes `action` straight
// through as `type`, so both the French and the English spellings can arrive.
const isBuy = /purchase|buy|achat/i.test(String(trade.type ?? row?.action ?? ''));

// performance is only meaningful when both prices exist — that is what it is
// computed between. A row missing either was skipped by the updater.
const stock_move_pct =
  rawPerf === null || txPrice === null || nowPrice === null
    ? null
    : (isBuy ? rawPerf : -rawPerf);

return [{
  json: {
    ...trade,
    is_buy: isBuy,
    stock_move_pct,
    transaction_price: txPrice,
    current_price: nowPrice,
    performance_source: row ? 'matched' : 'no-matching-row',
  },
}];

// Benchmark the same window against the S&P 500.
//
// No benchmark, no post. A return with nothing to compare it against is the
// single most misleading thing this workflow could publish — a +12% card during
// a +14% market is a losing trade dressed as a win. /api/sp500/historical returns
// [] rather than throwing when Alpaca is unreachable, so an empty array here is
// an ordinary outcome and has to be handled, not assumed away.

const trade = $('Pick Trade Row').first().json;

let bars = [];
try {
  bars = $input.all()
    .map(i => i.json)
    .filter(b => b && b.date && Number.isFinite(Number(b.close)))
    .map(b => ({ date: String(b.date).slice(0, 10), close: Number(b.close) }))
    .sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
} catch (e) {
  bars = [];
}

const tradeDate = String(trade.trade_date ?? '').slice(0, 10);
const exit = bars.length ? bars[bars.length - 1] : null;

// The entry bar has to be *near* the trade date, not merely on-or-after it. If
// Alpaca's window starts later than the trade (short history, a `months` cap, a
// truncated response) the first bar returned can be months late, and the index
// would then be scored over a shorter window than the stock — which quietly
// flatters or damns the trade. Ten days covers a holiday plus a long weekend.
const MAX_ENTRY_DRIFT_DAYS = 10;
const firstOnOrAfter = tradeDate ? bars.find(b => b.date >= tradeDate) : null;
const driftDays = firstOnOrAfter
  ? Math.round((new Date(firstOnOrAfter.date) - new Date(tradeDate)) / 86400000)
  : null;
const entry = driftDays !== null && driftDays <= MAX_ENTRY_DRIFT_DAYS ? firstOnOrAfter : null;

let benchmark_pct = null;
if (entry && exit && entry.close > 0 && exit.date > entry.date) {
  benchmark_pct = ((exit.close - entry.close) / entry.close) * 100;
}

const lag_days =
  trade.trade_date && trade.filed_date
    ? Math.round((new Date(trade.filed_date) - new Date(trade.trade_date)) / 86400000)
    : null;

// Number(null) is 0, and 0 is finite — so a bare Number.isFinite() check would
// wave a missing figure through as a flat 0.0% and post it. Reject the empty
// cases explicitly before coercing.
const numeric = v =>
  v !== null && v !== undefined && v !== '' && Number.isFinite(Number(v));

const hasMove = numeric(trade.stock_move_pct);
const hasBench = numeric(benchmark_pct);
const hasBoth = hasMove && hasBench;

const skip_reason = hasBoth
  ? null
  : !hasMove
    ? `no performance for trade ${trade.id} (${trade.performance_source})`
    : entry === null && firstOnOrAfter
      ? `S&P 500 history starts ${driftDays} days after the ${tradeDate} trade — window would not match`
      : `no S&P 500 window for ${tradeDate || 'unknown trade date'} (${bars.length} bars)`;

if (skip_reason) {
  console.log(`Skipping post: ${skip_reason}`);
}

return [{
  json: {
    ...trade,
    benchmark_pct,
    benchmark_label: 'S&P 500',
    benchmark_entry: entry ? entry.close : null,
    benchmark_exit: exit ? exit.close : null,
    lag_days,
    can_post: hasBoth,
    skip_reason,
  },
}];

// Build the Instagram caption and carry imageUrl forward.
const imageData = $input.first().json;
const trade = $('Compute Benchmark').first().json;

function fmt(n) {
  return n >= 1e6 ? `$${(n / 1e6).toFixed(1)}M` : `$${Math.round(n / 1e3)}K`;
}
function amount(min, max) {
  if (!min && !max) return 'Undisclosed';
  if (!max) return `${fmt(min)}+`;
  return `${fmt(min)} – ${fmt(max)}`;
}
function pct(n) {
  const v = Number(n);
  return `${v >= 0 ? '+' : ''}${v.toFixed(1)}%`;
}

const ticker = trade.ticker || '';
const isBuy = trade.is_buy === true;
const move = Number(trade.stock_move_pct);
const bench = Number(trade.benchmark_pct);
const lag = trade.lag_days;

const headline = isBuy
  ? `$${ticker} is ${pct(move)} since the buy`
  : `$${ticker} is ${pct(move)} since the sale`;

// The one sentence that must survive any edit to this template. `performance` is
// measured from the disclosed transaction price — it is the filer's window, not a
// follower's, because the filing only became public weeks later. Drop it and a
// data post becomes a performance claim the number does not support.
const basis = isBuy
  ? `Measured from the price at the disclosed transaction to the latest price we hold. That is the filer's result, not a follower's${lag !== null ? ` — the filing became public ${lag} days after the trade` : ''}.`
  : `Measured from the price at the disclosed sale to the latest price we hold — what the stock did after they got out${lag !== null ? `, disclosed ${lag} days later` : ''}.`;

const beat = move - bench;
const versus = `${ticker} ${pct(move)} vs ${trade.benchmark_label || 'S&P 500'} ${pct(bench)} over the same window (${pct(beat)} difference).`;

const caption = [
  `${isBuy ? '🟢' : '🔴'} ${headline}`,
  ``,
  `${trade.politician}${trade.party ? ` (${trade.party})` : ''} disclosed a ${isBuy ? 'purchase' : 'sale'} of $${ticker} worth ${amount(trade.amount_min, trade.amount_max)}.`,
  ``,
  `📊 ${versus}`,
  `📅 Traded: ${trade.trade_date || 'Unknown'}`,
  `📋 Disclosed: ${trade.filed_date || 'Unknown'}`,
  ``,
  basis,
  ``,
  trade.tagline,
  ``,
  `Every Congress filing, tracked and benchmarked: insideroption.com`,
  ``,
  `#CongressTrades #StockMarket #${ticker} #Investing #InsiderOption #SP500 #StockAct #WallStreet`,
].join('\n');

return [{ json: { ...trade, imageUrl: imageData.imageUrl, caption } }];

const container = $input.first().json;
const trade     = $('Build Caption').first().json;
return [{ json: { ...trade, containerId: container.id } }];

const staticData = $getWorkflowStaticData('global');
const trade = $('Save Container ID').first().json;
const ticker = String(trade.ticker ?? '').trim().toUpperCase();

const recentPublishedTickers = Array.isArray(staticData.recentPublishedTickers)
  ? staticData.recentPublishedTickers
      .map(value => String(value).trim().toUpperCase())
      .filter(Boolean)
      .slice(-9)
  : [];

if (ticker) {
  recentPublishedTickers.push(ticker);
}

staticData.recentPublishedTickers = recentPublishedTickers.slice(-10);

return [{
  json: {
    success: true,
    postedTradeId: trade.id,
    ticker,
    politician: trade.politician,
    trade_date: trade.trade_date,
    igPostId: $input.first().json.id,
    postedAt: new Date().toISOString(),
    recentPublishedTickers: staticData.recentPublishedTickers,
  },
}];
